"""Render docs/mcp-tools.md from the public catalog and the verb table.

``python -m synth_ai.mcp.catalog_doc > docs/mcp-tools.md``; a test keeps the
committed file equal to this output.
"""

from __future__ import annotations

from synth_ai.surface import VERBS

from .catalog import BY_NAME


def render() -> str:
    lines = [
        "# MCP tools",
        "",
        "Generated by `python -m synth_ai.mcp.catalog_doc`. One tool per CLI verb.",
        "",
        "| CLI | Tool | Scope | Mutates | May charge | Hosted |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for verb in VERBS:
        tool = BY_NAME[verb.tool]
        lines.append(
            f"| `synth {' '.join(verb.cli)}` | `{tool.name}` | {tool.scope or '-'} | "
            f"{'yes' if tool.mutates else 'no'} | {'yes' if tool.paid else 'no'} | "
            f"{'yes' if verb.hosted else 'no'} |"
        )
    lines += ["", "## Descriptions", ""]
    lines += [f"- `{BY_NAME[v.tool].name}`: {BY_NAME[v.tool].description}" for v in VERBS]
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    print(render(), end="")
